//! End-to-end hook delegation: a repository that owns its hooks through the
//! pre-commit framework must pass `doctor --strict`, report the delegation, and
//! keep its wrapper when `hook install` runs without `--force`.

#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::path::{Path, PathBuf};
use std::process::{Command, Output};

mod support;

use support::git_command;

/// A wrapper in the shape `pre-commit install` writes.
const PRE_COMMIT_WRAPPER: &str = "#!/usr/bin/env bash\n\
# File generated by pre-commit: https://pre-commit.com\n\
exec pre-commit hook-impl --hook-type=pre-commit\n";

fn harness() -> Command {
    let mut cmd = Command::new(env!("CARGO_BIN_EXE_do-harness"));
    support::isolate_command(&mut cmd);
    cmd
}

fn run(cmd: &mut Command) -> Output {
    let out = cmd.output().expect("spawn");
    assert!(
        out.status.success(),
        "command failed: {cmd:?}\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );
    out
}

fn git_ok(dir: &Path, args: &[&str]) {
    let out = git_command(dir).args(args).output().expect("spawn git");
    assert!(
        out.status.success(),
        "git {args:?} failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
}

/// Copies the harness binary outside `target/` so `doctor --strict` accepts it.
fn strict_harness_binary(root: &Path) -> PathBuf {
    let name = if cfg!(windows) {
        "do-harness-bin.exe"
    } else {
        "do-harness-bin"
    };
    let dest = root.join(name);
    std::fs::copy(env!("CARGO_BIN_EXE_do-harness"), &dest).expect("copy harness binary");
    dest
}

#[test]
fn delegated_pre_commit_hooks_pass_strict_and_survive_install() {
    let dir = tempfile::tempdir().expect("tempdir");
    let root = dir.path();
    run(harness().arg("--root").arg(root).arg("init"));
    git_ok(root, &["init", "-q"]);
    git_ok(root, &["config", "user.email", "e2e@example.test"]);
    git_ok(root, &["config", "user.name", "e2e"]);

    std::fs::write(root.join(".pre-commit-config.yaml"), "repos: []\n").expect("write config");
    for name in ["pre-commit", "pre-push", "commit-msg"] {
        std::fs::write(root.join(".git/hooks").join(name), PRE_COMMIT_WRAPPER)
            .expect("write pre-commit wrapper");
    }
    let bin = strict_harness_binary(root);

    let install = harness()
        .current_dir(root)
        .arg("--root")
        .arg(root)
        .args(["hook", "install"])
        .output()
        .expect("spawn hook install");
    assert!(
        !install.status.success(),
        "hook install must refuse to replace a delegated hook"
    );
    let install_err = String::from_utf8_lossy(&install.stderr);
    assert!(
        install_err.contains("pre-commit framework"),
        "{install_err}"
    );
    assert_eq!(
        std::fs::read_to_string(root.join(".git/hooks/pre-commit")).expect("read wrapper"),
        PRE_COMMIT_WRAPPER,
        "the delegated pre-commit hook must be preserved"
    );

    let status = run(harness()
        .current_dir(root)
        .arg("--root")
        .arg(root)
        .arg("hook")
        .arg("status")
        .env("DO_HARNESS_BIN", &bin));
    let status_stdout = String::from_utf8_lossy(&status.stdout);
    assert!(
        status_stdout.contains("delegated to pre-commit"),
        "status stdout: {status_stdout}"
    );

    let doctor = run(harness()
        .current_dir(root)
        .arg("--root")
        .arg(root)
        .args(["doctor", "--strict", "--format", "json"])
        .env("DO_HARNESS_BIN", &bin));
    let doctor_stdout = String::from_utf8_lossy(&doctor.stdout);
    let value: serde_json::Value = serde_json::from_str(doctor_stdout.trim()).expect("doctor json");
    assert_eq!(value["ok"], true, "{doctor_stdout}");
    assert_eq!(
        value["hooks"]["ownership"]["pre_commit"], "delegated_pre_commit",
        "{doctor_stdout}"
    );
    assert_eq!(
        value["hooks"]["ownership"]["commit_msg"], "delegated_pre_commit",
        "{doctor_stdout}"
    );
}
